'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)], uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join(''), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',remix:'M4 4h16v16H4z M9 4v16 M15 4v16 M4 9h16 M4 15h16',story:'M4 4h16v16H4z M8 8h8 M8 12h5 M8 16h8',library:'M3 7h18v14H3z M6 3h12v4 M10 11l5 3-5 3z',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16 M8 14h2 M14 14h2',channels:'M8 12a4 4 0 0 1 0-6l3-3a4 4 0 0 1 6 6l-1 1 M16 12a4 4 0 0 1 0 6l-3 3a4 4 0 0 1-6-6l1-1 M8 16l8-8',logs:'M5 3h14v18H5z M9 7h6 M9 11h6 M9 15h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',plus:'M12 4v16 M4 12h16',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v6h16v-6',play:'M8 4l12 8-12 8z',download:'M12 3v13 M7 11l5 5 5-5 M4 16v5h16v-5',check:'M4 12l5 5L20 6'};
const ico=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.remix}"/></svg>`;
const labels={home:'Tổng quan',remix:'Remix video',story:'Dựng theo phân cảnh',pro:'Biên tập timeline',html:'HTML → MP4',hyperframes:'HyperFrames Studio',automation:'Tự động tạo video',pipeline:'Ý tưởng & lịch tự động',sources:'Douyin / RedNote',library:'Kho video',calendar:'Kế hoạch đăng',channels:'Kênh TikTok',logs:'Nhật ký xử lý',settings:'Cài đặt'};
let db,state,page='home',current=null,selected=0,previewObject=null,previewFrame=0,previewRunning=false,rendering=false,cancelRender=false,toastTimer;const urls=new Map();
const dbReady=new Promise((resolve,reject)=>{const req=indexedDB.open('remix-studio-v1',1);req.onupgradeneeded=()=>{req.result.createObjectStore('state');req.result.createObjectStore('files')};req.onsuccess=()=>{db=req.result;resolve()};req.onerror=()=>reject(req.error)});
async function dbGet(store,key){await dbReady;return new Promise((resolve,reject)=>{const r=db.transaction(store).objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function dbPut(store,key,data){await dbReady;return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(data,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Không đủ dung lượng lưu trữ'))})}
async function dbDel(store,key){await dbReady;return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function save(){await dbPut('state','workspace',state)}
async function fileUrl(id){if(!id)return '';if(urls.has(id))return urls.get(id);const f=await dbGet('files',id);if(!f)return '';const u=URL.createObjectURL(f);urls.set(id,u);return u}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function log(message,type='info'){state.logs.unshift({id:uid(),message,type,at:new Date().toISOString()});state.logs=state.logs.slice(0,250)}
function time(sec){sec=Math.max(0,Number(sec)||0);return `${Math.floor(sec/60)}:${String(Math.round(sec%60)).padStart(2,'0')}`}
function duration(p){return p.scenes.reduce((a,s)=>a+Number(s.duration||0),0)}
function fmtDate(iso){return new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date(iso))}
function newProject(name='Video chưa đặt tên'){return {id:uid(),name,created:new Date().toISOString(),updated:new Date().toISOString(),ratio:'9:16',fit:'cover',color:'#ffffff',fontSize:38,musicVolume:.18,voiceVolume:1,originalAudio:true,scenes:[],output:null}}
function svgArt(kind){const colors=[['#d2e2df','#47776b','#e6d5be'],['#c4d4ee','#5075ad','#e6eaf4'],['#ecd8bd','#a38364','#f6eee2']][kind%3];return `<svg xmlns="http://www.w3.org/2000/svg" width="720" height="1280" viewBox="0 0 720 1280"><defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="${colors[0]}"/><stop offset="1" stop-color="${colors[1]}"/></linearGradient><filter id="shadow"><feGaussianBlur stdDeviation="18"/></filter></defs><rect width="720" height="1280" fill="url(#bg)"/><circle cx="600" cy="140" r="320" fill="white" opacity=".12"/><circle cx="100" cy="900" r="350" fill="white" opacity=".08"/><ellipse cx="370" cy="1020" rx="210" ry="35" fill="#26364b" opacity=".15" filter="url(#shadow)"/><path d="M150 930 Q360 850 570 930 L570 1000 Q360 1070 150 1000Z" fill="${colors[2]}"/><ellipse cx="360" cy="930" rx="210" ry="55" fill="#faf5ee"/>${kind===0?'<path d="M270 700h180l-18 230q-72 30-144 0z" fill="#eee5d5"/><path d="M360 700q-140-260-70-330 140 50 70 330 M360 690q130-260 180-210-5 170-180 210 M360 600q-15-330 65-360 80 110-65 360" fill="#446c59"/>':kind===1?'<rect x="220" y="440" width="280" height="490" rx="35" fill="#f0f1f3"/><rect x="260" y="380" width="200" height="85" rx="12" fill="#d4dce9"/><rect x="260" y="620" width="200" height="150" rx="2" fill="#7191bc"/><path d="M300 670h120 M320 700h80" stroke="white" stroke-width="5"/>':'<path d="M270 460h180v160q80 60 80 140v110q0 80-170 80t-170-80V760q0-80 80-140z" fill="#f1e7d4"/><ellipse cx="360" cy="460" rx="90" ry="18" fill="#d4c1a4"/><path d="M225 780q140-70 270 0 M215 820q150-70 290 0" fill="none" stroke="#e2d3ba" stroke-width="4"/>'}<text x="360" y="190" text-anchor="middle" fill="white" font-family="sans-serif" letter-spacing="9" font-size="18" opacity=".7">REMIX STUDIO</text></svg>`}
async function seed(){state={projects:[],channels:[],schedules:[],logs:[],settings:{name:'Không gian cá nhân'},version:1};const names=['Một góc xanh, một ngày mới','Kể câu chuyện sản phẩm','Vẻ đẹp từ điều giản đơn'];for(let i=0;i<3;i++){const p=newProject(names[i]),id=uid();await dbPut('files',id,new Blob([svgArt(i)],{type:'image/svg+xml'}));p.demo=true;p.scenes=[{id:uid(),fileId:id,type:'image',name:'Minh họa mẫu',duration:4,start:0,text:['Chạm vào một chút bình yên','Điều đặc biệt ở trong chi tiết','Đơn giản. Và thật khác biệt.'][i]}];state.projects.push(p)}log('Khởi tạo không gian và 3 dự án minh họa.');await save()}
paths.html=paths.story;paths.automation=paths.plus;paths.pro=paths.remix;paths.pipeline=paths.calendar;paths.sources=paths.download;paths.hyperframes=paths.play;
function nav(){let out='';for(const [key,label]of Object.entries(labels)){if(key==='calendar')out+='<div class="nav-divider"></div><div class="nav-label">QUẢN LÝ</div>';out+=`<a class="nav-item ${page===key?'active':''}" href="#${key}">${ico(key)}<span>${label}</span>${key==='library'?`<span class="count">${state.projects.filter(p=>p.output).length}</span>`:''}</a>`}$('#nav').innerHTML=out;$('#crumb').textContent=labels[page]||labels.home;$('.workspace div').innerHTML=`${esc(state.settings.name)}<small>Lưu trên thiết bị này</small>`}
function head(eyebrow,title,desc,actions=''){return `<div class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${desc}</p></div>${actions}</div>`}
function button(text,action,primary=false,icon=''){return `<button class="btn ${primary?'primary':''}" data-action="${action}">${icon?ico(icon):''}${text}</button>`}
async function go(next){if(rendering)return;stopPreview();window.HtmlStudio?.stop();window.AutoStudio?.stop();window.ProEditor?.stop();window.PipelineStudio?.stop();window.SourceStudio?.stop();window.HyperStudio?.stop();page=Object.hasOwn(labels,next)?next:'home';$('#sidebar').classList.remove('open');nav();if(page==='home')await home();if(page==='remix'||page==='story')await editor();if(page==='html')await window.HtmlStudio.open();if(page==='automation')await window.AutoStudio.open();if(page==='pro')await window.ProEditor.open();if(page==='pipeline')await window.PipelineStudio.open();if(page==='sources')await window.SourceStudio.open();if(page==='hyperframes')await window.HyperStudio.open();if(page==='library')await library();if(page==='calendar')calendar();if(page==='channels')channels();if(page==='logs')logs();if(page==='settings')await settings();}
async function projectCards(projects){if(!projects.length)return '<div class="panel empty"><h3>Chưa có dự án</h3><p>Bắt đầu bằng một ý tưởng hoặc tư liệu của bạn.</p>'+button('Tạo video đầu tiên','new',true,'plus')+'</div>';let html='';for(const p of projects){const scene=p.scenes[0];const u=scene?await fileUrl(scene.fileId):'';html+=`<article class="card"><div class="project-cover" data-open="${p.id}" style="background:#dce6f5">${u?(scene.type==='video'?`<video src="${u}" muted preload="metadata"></video>`:`<img src="${u}" alt="Tư liệu của ${esc(p.name)}">`):ico('remix')}<div class="cover-overlay"></div><span class="cover-badge">${p.demo?'DỰ ÁN MẪU':p.output?'ĐÃ XUẤT':'BẢN NHÁP'}</span><span class="cover-time">${time(duration(p))}</span></div><div class="card-body"><h3>${esc(p.name)}</h3><div class="card-meta"><span>${p.scenes.length} phân cảnh</span><span>·</span><span>${p.ratio}</span><span>·</span><span>${new Date(p.updated).toLocaleDateString('vi-VN')}</span></div><div class="card-bottom"><span class="badge ${p.output?'green':'gray'}">${p.output?'Sẵn sàng sử dụng':'Đang biên tập'}</span><div><button class="text-link" data-open="${p.id}">Mở dự án ↗</button><button class="text-link" data-project-menu="${p.id}" aria-label="Tùy chọn dự án">•••</button></div></div></div></article>`}return `<div class="cards">${html}</div>`}
async function home(){const outputs=state.projects.filter(p=>p.output).length;$('#main').innerHTML=head('SÁNG TẠO MỖI NGÀY','Hôm nay, bạn muốn kể gì?','Biến những tư liệu quen thuộc thành một câu chuyện mới.',button('Tạo video mới','new',true,'plus'))+`<section class="hero"><div class="hero-copy"><span class="eyebrow">MỘT Ý TƯỞNG. NHIỀU CÁCH KỂ.</span><h2>Từ tư liệu của bạn,<br>đến video mang dấu ấn riêng.</h2><p>Cắt ghép, thêm lời đọc và dựng theo phân cảnh.<br>Mọi thứ bạn cần, trong cùng một không gian.</p><div class="actions">${button('Bắt đầu sáng tạo','new',true,'plus')}<button class="text-link" data-action="guide">Khám phá quy trình ↗</button></div></div><div class="hero-art" aria-hidden="true"><div class="art-circle"></div><div class="art-tile back"><div class="art-vase plant"></div></div><div class="art-tile"><div class="art-vase"></div></div><div class="art-play">▶</div><span class="art-label">✦ Tạo bằng tư liệu của bạn</span></div></section><div class="stats">${[[state.projects.length,'Dự án sáng tạo','remix','dự án'],[outputs,'Video đã xuất','library','video'],[state.schedules.filter(s=>!s.done).length,'Kế hoạch sắp tới','calendar','lịch'],[state.channels.length,'Kênh đã ghi nhận','channels','kênh']].map(([n,t,i,unit])=>`<div class="stat"><div class="stat-icon">${ico(i)}</div><div><small>${t}</small><strong>${n}<sub>${unit}</sub></strong></div></div>`).join('')}</div><section><div class="section-head"><h2>Dự án gần đây</h2><button class="text-link" data-action="all-projects">Xem tất cả dự án →</button></div>${await projectCards([...state.projects].sort((a,b)=>b.updated.localeCompare(a.updated)).slice(0,3))}</section><div class="grid-bottom"><section class="panel"><div class="section-head"><h2>Kế hoạch đăng sắp tới</h2><a class="text-link" href="#calendar">Xem kế hoạch →</a></div>${scheduleRows(state.schedules.filter(s=>!s.done).slice(0,2),true)}</section><section class="panel"><div class="section-head"><h2>Một quy trình, thật gọn</h2><span class="badge">3 BƯỚC</span></div>${[['Chọn tư liệu của bạn','Thêm video hoặc ảnh, sắp xếp câu chuyện.'],['Tạo dấu ấn riêng','Cắt cảnh, chèn chữ, thêm nhạc và lời đọc.'],['Xuất video & lên kế hoạch','Tải tệp, chọn kênh và ghi nhận lịch đăng.']].map(([t,d],i)=>`<div class="step"><span class="step-num">0${i+1}</span><div><b>${t}</b><p>${d}</p></div></div>`).join('')}</section></div>`}
async function editor(){stopPreview();if(!current)current=state.projects[0]?.id;if(!current){$('#main').innerHTML=head('XƯỞNG SÁNG TẠO','Bắt đầu câu chuyện mới','Thêm tư liệu đầu tiên của bạn.')+button('Tạo dự án','new',true,'plus');return}const p=getProject();selected=Math.min(selected,Math.max(0,p.scenes.length-1));const s=p.scenes[selected];$('#main').innerHTML=head('XƯỞNG SÁNG TẠO',page==='story'?'Dựng theo phân cảnh':'Remix video','Tự do sắp xếp tư liệu, âm thanh và câu chữ.',`<div class="actions">${button('Dự án mới','new',false,'plus')}${button('Xuất video','render',true,'download')}</div>`)+`<div class="editor"><div><div class="panel"><div class="editor-title"><input class="title-edit" id="project-name" aria-label="Tên dự án" value="${esc(p.name)}"></div><div class="preview-wrap"><canvas id="preview" width="540" height="960" aria-label="Xem trước video"></canvas></div><div class="preview-actions">${button('Xem thử','preview',false,'play')}<span class="badge gray">${p.ratio} · ${time(duration(p))}</span><span class="badge gray">${p.scenes.length} cảnh</span></div></div><div class="panel"><div class="section-head"><h2>Phân cảnh của bạn</h2><div class="actions"><button class="text-link" data-action="script">Tách từ kịch bản</button><button class="text-link" data-action="upload">+ Thêm tư liệu</button></div></div><div id="scenes"></div><div class="spacer"></div><div class="dropzone" id="dropzone" tabindex="0" role="button" aria-label="Chọn ảnh hoặc video">${ico('upload')}<b>Kéo thả tư liệu vào đây</b><small>Hoặc bấm để chọn ảnh / video · Tối đa 250 MB mỗi tệp</small></div><input id="media-input" type="file" accept="image/*,video/*" multiple hidden></div></div><div class="editor-settings"><div class="panel"><div class="section-head"><h2>Cài đặt video</h2><span class="badge">BẢN WEB</span></div><div class="field"><label for="ratio">Tỷ lệ khung hình</label><select id="ratio">${['9:16','16:9','1:1'].map(r=>`<option ${p.ratio===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="field"><label for="fit">Hiển thị tư liệu</label><select id="fit"><option value="cover" ${p.fit==='cover'?'selected':''}>Lấp đầy khung hình</option><option value="contain" ${p.fit==='contain'?'selected':''}>Giữ trọn tư liệu</option></select></div><label class="check"><input type="checkbox" id="original-audio" ${p.originalAudio?'checked':''}>Giữ âm thanh video gốc</label><p class="note">Xuất bằng trình duyệt, thời gian dựng gần bằng độ dài video. Định dạng tùy hỗ trợ của thiết bị.</p></div><div class="panel"><div class="section-head"><h2>${s?`Phân cảnh ${selected+1}`:'Chưa có phân cảnh'}</h2></div>${s?`<div class="field"><label for="scene-text">Chữ hiển thị</label><textarea id="scene-text" maxlength="350" placeholder="Viết một câu cho phân cảnh này…">${esc(s.text)}</textarea></div><div class="two"><div class="field"><label for="scene-duration">Thời lượng (giây)</label><input id="scene-duration" type="number" min="0.5" max="120" step="0.5" value="${s.duration}"></div><div class="field"><label for="scene-start">Cắt từ giây</label><input id="scene-start" type="number" min="0" step="0.1" value="${s.start||0}" ${s.type==='image'?'disabled':''}></div></div><div class="two"><div class="field"><label for="text-color">Màu chữ</label><input type="color" id="text-color" value="${p.color}"></div><div class="field"><label for="font-size">Cỡ chữ</label><input type="number" id="font-size" min="20" max="70" value="${p.fontSize}"></div></div><small class="note">${esc(s.name)}${s.type==='video'?` · Gốc: ${time(s.mediaDuration)}`:''}</small>`:'<p class="note">Thêm ảnh hoặc video để bắt đầu chỉnh sửa.</p>'}</div><div class="panel"><div class="section-head"><h2>Âm thanh & lời đọc</h2></div><div class="field"><label>Nhạc nền</label><button class="btn full" data-action="music">${p.musicId?'Đổi nhạc nền':'＋ Chọn tệp nhạc'}</button><span class="file-name">${esc(p.musicName||'MP3, WAV hoặc M4A của bạn')}</span>${p.musicId?'<button class="text-link" data-remove-audio="music">Gỡ nhạc</button>':''}<label for="music-volume" class="note">Âm lượng nhạc</label><input id="music-volume" type="range" min="0" max="1" step=".05" value="${p.musicVolume}"></div><div class="field"><label>Lời đọc</label><button class="btn full" data-action="voice">${p.voiceId?'Đổi tệp lời đọc':'＋ Thêm tệp giọng đọc'}</button><span class="file-name">${esc(p.voiceName||'Lời đọc thu sẵn hoặc tệp từ dịch vụ TTS')}</span>${p.voiceId?'<button class="text-link" data-remove-audio="voice">Gỡ lời đọc</button>':''}<label for="voice-volume" class="note">Âm lượng lời đọc</label><input id="voice-volume" type="range" min="0" max="1" step=".05" value="${p.voiceVolume}"></div><input id="audio-input" type="file" accept="audio/*" hidden><p class="note">Chưa kết nối dịch vụ tạo giọng AI. Bạn có thể dùng tệp giọng nữ miền Nam thu sẵn.</p></div></div></div>`;await sceneList();bindEditor();await drawPreview()}
function getProject(){return state.projects.find(p=>p.id===current)}
async function sceneList(){const p=getProject();let html='';for(let i=0;i<p.scenes.length;i++){const s=p.scenes[i],u=await fileUrl(s.fileId);html+=`<div class="scene-row ${i===selected?'selected':''}" data-scene="${i}"><span class="scene-number">${String(i+1).padStart(2,'0')}</span>${s.type==='image'?`<img class="scene-thumb" src="${u}" alt="Cảnh ${i+1}">`:`<video class="scene-thumb" src="${u}" muted preload="metadata"></video>`}<div><h4>${esc(s.text||s.name)}</h4><p>${s.type==='video'?'Video':'Ảnh'} · ${time(s.duration)}</p></div><div class="scene-buttons"><button data-move="${i},-1" aria-label="Đưa cảnh lên">↑</button><button data-move="${i},1" aria-label="Đưa cảnh xuống">↓</button><button data-delete-scene="${i}" aria-label="Xóa cảnh">×</button></div></div>`}$('#scenes').innerHTML=html||'<p class="note">Câu chuyện của bạn sẽ xuất hiện ở đây.</p>'}
async function updateProject(){const p=getProject();p.updated=new Date().toISOString();p.outputStale=!!p.output;p.demo=false;await save()}
function bindEditor(){const p=getProject();$('#project-name').onchange=async e=>{p.name=e.target.value.trim()||'Video chưa đặt tên';await updateProject()};for(const id of ['ratio','fit','text-color','font-size','original-audio','music-volume','voice-volume']){const el=$('#'+id);if(el)el.onchange=async()=>{if(id==='ratio')p.ratio=el.value;if(id==='fit')p.fit=el.value;if(id==='text-color')p.color=el.value;if(id==='font-size')p.fontSize=Math.max(20,Math.min(70,Number(el.value)||38));if(id==='original-audio')p.originalAudio=el.checked;if(id==='music-volume')p.musicVolume=Number(el.value);if(id==='voice-volume')p.voiceVolume=Number(el.value);await updateProject();stopPreview();await drawPreview()}}for(const id of ['scene-text','scene-duration','scene-start']){const el=$('#'+id);if(el)el.onchange=async()=>{const s=p.scenes[selected];if(id==='scene-text')s.text=el.value;if(id==='scene-duration')s.duration=Math.max(.5,Math.min(120,Number(el.value)||4));if(id==='scene-start')s.start=Math.max(0,Math.min((s.mediaDuration||120)-.5,Number(el.value)||0));if(s.type==='video')s.duration=Math.max(.1,Math.min(s.duration,s.mediaDuration-s.start));await updateProject();stopPreview();await editor()}}$('#media-input').onchange=e=>addFiles([...e.target.files]).catch(report);const dz=$('#dropzone');dz.onclick=()=>$('#media-input').click();dz.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')$('#media-input').click()};dz.ondragover=e=>{e.preventDefault();dz.style.borderColor='#2563eb'};dz.ondragleave=()=>dz.style.borderColor='';dz.ondrop=e=>{e.preventDefault();dz.style.borderColor='';addFiles([...e.dataTransfer.files]).catch(report)}}
function loaded(el,event){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{cleanup();reject(new Error('Tệp không tải được hoặc định dạng chưa được hỗ trợ.'))},15000);function cleanup(){clearTimeout(timer);el.removeEventListener(event,ok);el.removeEventListener('error',fail)}function ok(){cleanup();resolve(el)}function fail(){cleanup();reject(new Error('Không đọc được tư liệu. Hãy thử tệp khác.'))}el.addEventListener(event,ok,{once:true});el.addEventListener('error',fail,{once:true})})}
async function mediaFor(s){const u=await fileUrl(s.fileId);if(!u)throw new Error('Thiếu tệp tư liệu. Hãy thêm lại tư liệu cho dự án.');if(s.type==='image'){const el=new Image(),promise=loaded(el,'load');el.src=u;await promise;return el}const el=document.createElement('video');el.playsInline=true;el.preload='auto';const promise=loaded(el,'loadeddata');el.src=u;await promise;if(s.start>0){const seek=loaded(el,'seeked');el.currentTime=s.start;await seek}return el}
async function addFiles(files){if(files.length>30)throw new Error('Mỗi lần thêm tối đa 30 tệp.');toast('Đang đọc tư liệu…');let count=0;for(const f of files){if(!/^(image|video)\//.test(f.type)){toast(`Bỏ qua ${f.name}: không phải ảnh/video.`);continue}if(f.size>250*1024*1024){toast(`Bỏ qua ${f.name}: vượt 250 MB.`);continue}const id=uid(),s={id:uid(),fileId:id,type:f.type.startsWith('video')?'video':'image',name:f.name,duration:4,start:0,text:''};await dbPut('files',id,f);try{if(s.type==='video'){const el=await mediaFor(s);if(!Number.isFinite(el.duration)||el.duration<=0)throw new Error('Không xác định được độ dài video.');s.mediaDuration=el.duration;s.duration=Math.min(8,el.duration);el.removeAttribute('src');el.load()}getProject().scenes.push(s);count++}catch(e){await dbDel('files',id);toast(`${f.name}: ${e.message}`)}}if(count){log(`Thêm ${count} tư liệu vào “${getProject().name}”.`);selected=getProject().scenes.length-1;await updateProject();await editor();toast(`Đã thêm ${count} tư liệu.`)}}
function dimensions(p){return p.ratio==='16:9'?[960,540]:p.ratio==='1:1'?[720,720]:[540,960]}
function wrapText(ctx,text,maxWidth){const lines=[];for(const para of String(text).split('\n')){let line='';for(const word of para.split(/\s+/)){if(!word)continue;const next=line?line+' '+word:word;if(ctx.measureText(next).width>maxWidth&&line){lines.push(line);line=word}else line=next}if(line)lines.push(line)}return lines.slice(0,7)}
function paint(canvas,media,s,p){const ctx=canvas.getContext('2d'),[w,h]=dimensions(p);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}ctx.fillStyle='#142743';ctx.fillRect(0,0,w,h);if(media){const mw=media.videoWidth||media.naturalWidth,mh=media.videoHeight||media.naturalHeight;if(mw&&mh){const scale=p.fit==='contain'?Math.min(w/mw,h/mh):Math.max(w/mw,h/mh);ctx.drawImage(media,(w-mw*scale)/2,(h-mh*scale)/2,mw*scale,mh*scale)}}if(s?.text){const size=p.fontSize*(w/540);ctx.font=`600 ${size}px system-ui, sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';const lines=wrapText(ctx,s.text,w*.82),lh=size*1.4,y=h*.79-(lines.length-1)*lh/2;const gradient=ctx.createLinearGradient(0,h*.57,0,h);gradient.addColorStop(0,'#0000');gradient.addColorStop(1,'#0009');ctx.fillStyle=gradient;ctx.fillRect(0,h*.57,w,h*.43);ctx.fillStyle=p.color;ctx.shadowColor='#0009';ctx.shadowBlur=8;for(let i=0;i<lines.length;i++)ctx.fillText(lines[i],w/2,y+i*lh,w*.9);ctx.shadowBlur=0}if(!media){ctx.fillStyle='#8fa9d1';ctx.font='22px system-ui';ctx.textAlign='center';ctx.fillText('Thêm tư liệu để bắt đầu',w/2,h/2)}}
async function drawPreview(){if(!$('#preview'))return;const p=getProject(),s=p.scenes[selected];const old=previewObject;previewObject=null;if(old instanceof HTMLVideoElement){old.pause();old.removeAttribute('src');old.load()}try{if(s)previewObject=await mediaFor(s);if(previewObject instanceof HTMLVideoElement)previewObject.muted=true;if($('#preview'))paint($('#preview'),previewObject,s,p)}catch(e){toast(e.message);if($('#preview'))paint($('#preview'),null,s,p)}}
function stopPreview(){previewRunning=false;cancelAnimationFrame(previewFrame);if(previewObject instanceof HTMLVideoElement)previewObject.pause()}
async function playPreview(){if(previewRunning){stopPreview();return}const p=getProject();if(!p.scenes.length){toast('Hãy thêm ít nhất một tư liệu.');return}previewRunning=true;let i=selected;while(previewRunning&&i<p.scenes.length){const s=p.scenes[i];previewObject=await mediaFor(s);if(!previewRunning)break;const m=previewObject;if(m instanceof HTMLVideoElement){m.muted=true;await m.play()}const t=performance.now();await new Promise(resolve=>{function tick(){if(!previewRunning||!$('#preview')){resolve();return}paint($('#preview'),m,s,p);if(performance.now()-t>=s.duration*1000){resolve();return}previewFrame=requestAnimationFrame(tick)}tick()});if(m instanceof HTMLVideoElement)m.pause();i++}previewRunning=false;if($('#preview'))await drawPreview()}
async function library(){const filter=window.libraryFilter||'all';let ps=state.projects.filter(p=>filter==='all'||(filter==='exported'?p.output:!p.output));const term=(window.librarySearch||'').toLowerCase();ps=ps.filter(p=>p.name.toLowerCase().includes(term));$('#main').innerHTML=head('THƯ VIỆN SÁNG TẠO','Kho video & dự án','Tất cả tư liệu đã dựng, sẵn sàng cho câu chuyện tiếp theo.',button('Tạo video mới','new',true,'plus'))+`<div class="toolbar"><input id="search-project" placeholder="Tìm theo tên dự án…" aria-label="Tìm dự án" value="${esc(window.librarySearch||'')}"><div class="segmented"><button data-filter="all" class="${filter==='all'?'active':''}">Tất cả</button><button data-filter="draft" class="${filter==='draft'?'active':''}">Bản nháp</button><button data-filter="exported" class="${filter==='exported'?'active':''}">Đã xuất</button></div><span class="right note">${ps.length} dự án</span></div>${await projectCards(ps)}<div class="info">Dự án và tệp được lưu trong trình duyệt này. Hãy tải video về và sao lưu dự án trước khi xóa dữ liệu trình duyệt hoặc đổi thiết bị.</div>`;$('#search-project').oninput=e=>{window.librarySearch=e.target.value;const pos=e.target.selectionStart;library().then(()=>{$('#search-project').focus();$('#search-project').setSelectionRange(pos,pos)})}}
function scheduleRows(items,compact=false){if(!items.length)return `<div class="empty">${ico('calendar')}<h3>Chưa có lịch đăng</h3><p>Chọn một video và lên kế hoạch cho lần xuất hiện tiếp theo.</p>${button('Lên kế hoạch','schedule',false,'plus')}</div>`;return [...items].sort((a,b)=>a.at.localeCompare(b.at)).map(s=>{const p=state.projects.find(p=>p.id===s.projectId),ch=state.channels.find(c=>c.id===s.channelId),date=new Date(s.at),over=date<Date.now()&&!s.done;return `<div class="schedule-row"><div class="date-box">TH ${new Intl.DateTimeFormat('en',{month:'numeric',timeZone:'Asia/Ho_Chi_Minh'}).format(date)}<b>${new Intl.DateTimeFormat('en',{day:'numeric',timeZone:'Asia/Ho_Chi_Minh'}).format(date)}</b></div><div class="schedule-copy"><h3>${esc(p?.name||'Dự án đã xóa')}</h3><p>${esc(ch?.name||'Chưa chọn kênh')} · ${fmtDate(s.at)} (giờ VN)</p>${compact?'':`<p>${esc(s.caption||'Chưa có chú thích')}</p>`}</div><span class="badge ${s.done?'green':over?'amber':'gray'}">${s.done?'Đã đánh dấu đăng':over?'Đến hạn · đăng thủ công':'Dự kiến · đăng thủ công'}</span>${compact?'':`<div class="actions">${p?.output?`<button class="btn tiny" data-download="${p.id}">Tải video</button>`:''}<button class="text-link" data-schedule-edit="${s.id}">Sửa</button><button class="text-link" data-schedule-done="${s.id}">${s.done?'Hoàn tác':'Đánh dấu đã đăng'}</button><button class="text-link" data-schedule-delete="${s.id}">×</button></div>`}</div>`}).join('')}
function calendar(){const today=new Date(),days=[];for(let i=0;i<7;i++){const d=new Date(today);d.setDate(d.getDate()+i);const key=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Ho_Chi_Minh'}).format(d);days.push(`<div class="calendar-day ${i===0?'today':''}">${i===0?'HÔM NAY':d.toLocaleDateString('vi-VN',{weekday:'short',timeZone:'Asia/Ho_Chi_Minh'}).toUpperCase()}<strong>${d.toLocaleDateString('vi-VN',{day:'2-digit',timeZone:'Asia/Ho_Chi_Minh'})}</strong>${state.schedules.some(s=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Ho_Chi_Minh'}).format(new Date(s.at))===key)?'<i></i>':'<i style="opacity:0"></i>'}</div>`)}$('#main').innerHTML=head('PHÂN PHỐI NỘI DUNG','Kế hoạch đăng video','Sắp xếp nhịp sáng tạo của bạn. Mọi lịch hiển thị theo giờ Việt Nam.',button('Lên kế hoạch','schedule',true,'plus'))+`<div class="calendar-week">${days.join('')}</div><div class="info amber">Chế độ hiện tại: ghi nhận kế hoạch, tải video và đăng thủ công. Lịch không tự gửi video lên TikTok và không chạy nhắc nền khi bạn đóng trang.</div><div class="panel"><div class="section-head"><h2>Danh sách kế hoạch</h2><span class="badge gray">${state.schedules.length} lịch</span></div>${scheduleRows(state.schedules)}</div>`}
function channels(){$('#main').innerHTML=head('KẾT NỐI & QUẢN LÝ','Kênh TikTok của bạn','Ghi nhận các kênh để phân bổ nội dung và kế hoạch đăng.',button('Thêm kênh','channel',true,'plus'))+`<div class="info amber">Chưa tích hợp đăng nhập TikTok OAuth. Kênh thêm ở đây là thông tin quản lý do bạn nhập, chưa được xác minh và chưa cấp quyền đăng bài.</div><div class="panel"><div class="section-head"><h2>Danh sách kênh</h2><span class="badge gray">${state.channels.length} kênh</span></div>${state.channels.length?state.channels.map(c=>`<div class="channel-row"><span class="channel-avatar">♪</span><div class="channel-copy"><h3>${esc(c.name)}</h3><small>@${esc(c.username)}</small></div><span class="badge gray">Chưa kết nối API</span><button class="btn tiny" data-channel-edit="${c.id}">Chỉnh sửa</button><button class="text-link" data-channel-delete="${c.id}">Gỡ</button></div>`).join(''):`<div class="empty">${ico('channels')}<h3>Thêm kênh đầu tiên</h3><p>Tập trung kế hoạch của các kênh tại một nơi.</p>${button('Thêm thông tin kênh','channel',false,'plus')}</div>`}</div><div class="panel"><h3 style="font-size:14px;margin-top:0">Để bật đăng tự động trong bản tích hợp</h3><div class="step"><span class="step-num">01</span><div><b>Ứng dụng TikTok Developer</b><p>Cấu hình Login Kit, Content Posting API và quyền video.publish.</p></div></div><div class="step"><span class="step-num">02</span><div><b>Máy chủ và kho video</b><p>Lưu token an toàn, làm mới quyền, thực hiện lịch bằng tiến trình nền.</p></div></div><div class="step"><span class="step-num">03</span><div><b>Xét duyệt và đồng ý của chủ kênh</b><p>Đăng công khai phụ thuộc audit của TikTok. Mọi bài cần được chủ kênh kiểm soát.</p></div></div><a class="text-link" href="https://developers.tiktok.com/docs/content-posting-api-get-started" target="_blank" rel="noopener">Xem tài liệu TikTok chính thức ↗</a></div>`}
function logs(){$('#main').innerHTML=head('THEO DÕI HOẠT ĐỘNG','Nhật ký xử lý','Ghi nhận các thao tác thực tế trong không gian của bạn.',button('Xuất nhật ký','export-logs',false,'download'))+`<div class="panel">${state.logs.length?state.logs.map(l=>`<div class="log-row"><span class="log-dot" style="${l.type==='error'?'background:#d88686':''}"></span><div>${esc(l.message)}<small>${fmtDate(l.at)} · ${l.type==='error'?'Lỗi':'Hoạt động'}</small></div></div>`).join(''):'<div class="empty">Chưa có hoạt động.</div>'}</div>`}
async function settings(){const estimate=await navigator.storage?.estimate?.().catch(()=>({}))||{};const used=(estimate.usage||0)/1024/1024;$('#main').innerHTML=head('KHÔNG GIAN CÁ NHÂN','Cài đặt','Quản lý dữ liệu và cách bạn làm việc.')+`<div class="settings-grid"><div class="panel"><h3 style="margin-top:0;font-size:15px">Không gian làm việc</h3><div class="field"><label for="workspace-name">Tên không gian</label><input id="workspace-name" maxlength="50" value="${esc(state.settings.name)}"></div>${button('Lưu cài đặt','save-settings',true)}<div class="spacer"></div><p class="note">Múi giờ kế hoạch: Asia/Ho_Chi_Minh (UTC+7).</p></div><div class="panel"><h3 style="margin-top:0;font-size:15px">Dữ liệu trên thiết bị</h3><b style="font-size:25px">${estimate.usage!==undefined?used.toFixed(1):"—"} <small style="font-size:12px" class="muted">${estimate.usage!==undefined?"MB đang dùng":"Chưa có ước tính dung lượng"}</small></b><div class="storage-bar"><span style="width:${Math.min(100,used/((estimate.quota||1)/1024/1024)*100)}%"></span></div><p class="note">Tệp lưu bằng IndexedDB, không tự đồng bộ sang thiết bị khác. Trình duyệt có thể thu hồi dữ liệu khi thiếu dung lượng.</p>${button('Xin lưu bền vững','persist')}</div><div class="panel"><h3 style="margin-top:0;font-size:15px">Sao lưu & khôi phục</h3><p class="note">Sao lưu toàn bộ dự án, tư liệu và video đã xuất vào một tệp JSON. Tệp có thể lớn; cần đủ bộ nhớ thiết bị.</p><div class="spacer"></div><div class="actions">${button('Tải bản sao lưu','backup',true,'download')}${button('Khôi phục','restore')}</div><input type="file" id="restore-input" accept="application/json,.json" hidden></div><div class="panel"><h3 style="margin-top:0;font-size:15px">Mã nguồn & hướng dẫn</h3><p class="note">Mã nguồn tự viết, không phụ thuộc giao diện hoặc mã của công cụ trong ảnh. Gói tải gồm giao diện web, bộ xuất MP4 bằng FFmpeg và hướng dẫn Windows.</p><div class="spacer"></div><a class="btn" href="remix-studio-source.zip" download>${ico('download')} Tải toàn bộ mã nguồn</a><div class="spacer"></div>${button('Hướng dẫn sử dụng','guide')}</div></div>`;$('#restore-input').onchange=e=>restore(e.target.files[0]).catch(report)}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
function closeModal(){$('#modal').close()}
function guide(){modal(`<span class="eyebrow">BẮT ĐẦU VỚI REMIX STUDIO</span><h2>Từ ý tưởng đến video</h2><ol class="help-list"><li><b>Tạo dự án</b>, chọn ảnh/video trên thiết bị. Hoặc mở một dự án mẫu để thử ngay.</li><li><b>Chọn từng phân cảnh</b> để cắt thời điểm bắt đầu, chỉnh thời lượng, nội dung chữ. Dùng ↑ ↓ để đổi thứ tự.</li><li><b>Chọn tỷ lệ</b> 9:16, 16:9 hoặc 1:1. Thêm nhạc nền và giọng đọc bằng tệp âm thanh.</li><li><b>Xuất video</b> và giữ tab mở. Video được dựng thực tế ngay trên trình duyệt, không cần API. Xem trước chỉ minh họa hình, xuất video mới ghép âm thanh.</li><li><b>Tải video</b> về trước khi đóng trang. Ghi nhận kênh và kế hoạch để đăng thủ công.</li></ol><div class="info">Khuyên dùng Chrome/Edge trên máy tính. Nếu trình duyệt không xuất MP4, kết quả là WebM; dùng bộ xuất FFmpeg trong gói mã nguồn để có MP4. Mục HTML → MP4 có Edge TTS/Piper trong bản cục bộ. Chưa có AI tạo hình/video hoặc tự đăng TikTok.</div><div class="actions"><button class="btn primary" data-action="close-modal">Đã hiểu</button></div>`)}
function newDialog(){modal(`<span class="eyebrow">KHỞI ĐẦU MỚI</span><h2>Câu chuyện tiếp theo của bạn</h2><p>Đặt tên để dễ tìm lại. Bạn có thể đổi bất cứ lúc nào.</p><form id="new-form"><div class="field"><label for="new-name">Tên dự án</label><input id="new-name" required maxlength="100" placeholder="Ví dụ: Bộ sưu tập mùa mới" autofocus></div><div class="field"><label for="new-ratio">Tỷ lệ khung hình</label><select id="new-ratio"><option>9:16</option><option>16:9</option><option>1:1</option></select></div><div class="actions"><button type="button" class="btn" data-action="close-modal">Để sau</button><button class="btn primary">Tạo dự án →</button></div></form>`);$('#new-form').onsubmit=async e=>{e.preventDefault();const p=newProject($('#new-name').value.trim());if(!p.name)return;p.ratio=$('#new-ratio').value;state.projects.unshift(p);current=p.id;selected=0;log(`Tạo dự án “${p.name}”.`);await save();closeModal();location.hash='remix';await go('remix')};setTimeout(()=>$('#new-name')?.focus(),50)}
function channelDialog(id){const c=state.channels.find(c=>c.id===id);modal(`<span class="eyebrow">THÔNG TIN QUẢN LÝ</span><h2>${c?'Chỉnh sửa kênh':'Thêm kênh TikTok'}</h2><p>Thông tin do bạn nhập, không đăng nhập hoặc cấp quyền TikTok.</p><form id="channel-form"><div class="field"><label for="channel-name">Tên kênh</label><input id="channel-name" required maxlength="80" value="${esc(c?.name||'')}" placeholder="Tên hiển thị của kênh"></div><div class="field"><label for="channel-handle">Tên người dùng</label><input id="channel-handle" required maxlength="50" value="${esc(c?.username||'')}" placeholder="@tenkenh"></div><div class="actions"><button type="button" class="btn" data-action="close-modal">Hủy</button><button class="btn primary">Lưu thông tin</button></div></form>`);$('#channel-form').onsubmit=async e=>{e.preventDefault();const name=$('#channel-name').value.trim(),username=$('#channel-handle').value.trim().replace(/^@/,'');if(!name||!username)return;if(state.channels.some(x=>x.id!==id&&x.username.toLowerCase()===username.toLowerCase())){toast('Kênh này đã có trong danh sách.');return}if(c)Object.assign(c,{name,username});else state.channels.push({id:uid(),name,username});log(`${c?'Cập nhật':'Thêm'} thông tin kênh @${username}.`);await save();closeModal();await go('channels')}}
function vnInput(iso){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(iso)).replace(' ','T')}
function scheduleDialog(id){if(!state.projects.length){toast('Tạo một dự án trước khi lên kế hoạch.');return}const s=state.schedules.find(s=>s.id===id);modal(`<span class="eyebrow">KẾ HOẠCH NỘI DUNG</span><h2>${s?'Chỉnh sửa kế hoạch':'Lên kế hoạch đăng'}</h2><p>Lưu kế hoạch để bạn tự đăng video. Chưa có đăng tự động.</p><form id="schedule-form"><div class="field"><label for="schedule-project">Dự án / video</label><select id="schedule-project">${state.projects.map(p=>`<option value="${p.id}" ${(s?.projectId||current)===p.id?'selected':''}>${esc(p.name)} ${p.output?'· Đã xuất':'· Chưa xuất'}</option>`).join('')}</select></div><div class="field"><label for="schedule-channel">Kênh dự kiến</label><select id="schedule-channel"><option value="">Chưa chọn kênh</option>${state.channels.map(c=>`<option value="${c.id}" ${s?.channelId===c.id?'selected':''}>${esc(c.name)} · @${esc(c.username)}</option>`).join('')}</select></div><div class="field"><label for="schedule-at">Thời gian đăng (giờ Việt Nam, UTC+7)</label><input id="schedule-at" type="datetime-local" required value="${vnInput(s?.at||new Date(Date.now()+3600000).toISOString())}"></div><div class="field"><label for="schedule-caption">Chú thích & hashtag</label><textarea id="schedule-caption" maxlength="2200" placeholder="Kể thêm câu chuyện của video…">${esc(s?.caption||'')}</textarea></div><div class="actions"><button type="button" class="btn" data-action="close-modal">Hủy</button><button class="btn primary">Lưu kế hoạch</button></div></form>`);$('#schedule-form').onsubmit=async e=>{e.preventDefault();const at=new Date($('#schedule-at').value+':00+07:00');if(!Number.isFinite(+at)){toast('Thời gian không hợp lệ.');return}if(!s&&at<=new Date()){toast('Chọn thời điểm trong tương lai.');return}const data={projectId:$('#schedule-project').value,channelId:$('#schedule-channel').value,at:at.toISOString(),caption:$('#schedule-caption').value};if(s)Object.assign(s,data);else state.schedules.push({id:uid(),done:false,...data});log('Lưu kế hoạch đăng thủ công lúc '+fmtDate(data.at)+'.');await save();closeModal();location.hash='calendar';await go('calendar');toast('Đã lưu kế hoạch. Video chưa được gửi lên TikTok.')}}
function scriptDialog(){modal(`<span class="eyebrow">KỊCH BẢN → PHÂN CẢNH</span><h2>Chia câu chuyện thành từng cảnh</h2><p>Mỗi dòng tạo một cảnh chữ nền đơn sắc, sau đó bạn có thể thêm tư liệu. Đây là tách văn bản theo dòng, không dùng AI.</p><form id="script-form"><div class="field"><label for="script-text">Nội dung từng cảnh</label><textarea id="script-text" rows="6" required placeholder="Một khởi đầu mới\nNhững chi tiết tạo nên khác biệt\nKhám phá cùng chúng tôi"></textarea></div><div class="field"><label for="script-duration">Thời lượng mỗi cảnh (giây)</label><input id="script-duration" type="number" min="1" max="30" value="4" required></div><div class="actions"><button type="button" class="btn" data-action="close-modal">Hủy</button><button class="btn primary">Thêm các phân cảnh</button></div></form>`);$('#script-form').onsubmit=async e=>{e.preventDefault();const lines=$('#script-text').value.split('\n').map(s=>s.trim()).filter(Boolean).slice(0,30);const dur=Math.max(1,Math.min(30,Number($('#script-duration').value)||4));for(const text of lines){const id=uid();await dbPut('files',id,new Blob(['<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1920"><rect width="100%" height="100%" fill="#1b3158"/></svg>'],{type:'image/svg+xml'}));getProject().scenes.push({id:uid(),fileId:id,name:'Cảnh kịch bản',type:'image',duration:dur,start:0,text:text.slice(0,350)})}log(`Tạo ${lines.length} cảnh từ kịch bản.`);await updateProject();closeModal();await editor()}}
function projectMenu(id){const p=state.projects.find(p=>p.id===id);modal(`<span class="eyebrow">DỰ ÁN</span><h2>${esc(p.name)}</h2><p>${p.scenes.length} phân cảnh · ${time(duration(p))} · ${p.ratio}</p>${p.outputStale?'<div class="info amber">Video đã xuất là phiên bản trước khi chỉnh sửa. Hãy xuất lại để áp dụng thay đổi.</div>':''}<div style="display:grid;gap:10px"><button class="btn primary" data-open="${id}">Mở trình biên tập</button>${p.output?`<button class="btn" data-watch="${id}">Xem & tải video đã xuất</button><button class="btn" data-pro-from-library="${id}">Mở trong Biên tập timeline</button>`:''}<button class="btn" data-duplicate="${id}">Nhân bản dự án</button><button class="btn danger" data-delete-project="${id}">Xóa dự án…</button></div><div class="actions"><button class="btn" data-action="close-modal">Đóng</button></div>`)}
async function watch(id){const p=state.projects.find(p=>p.id===id);const u=await fileUrl(p.output.fileId);if(!u)throw new Error('Không tìm thấy tệp xuất. Hãy xuất lại video.');modal(`<span class="eyebrow">VIDEO ĐÃ XUẤT</span><h2>${esc(p.name)}</h2><p>${p.output.mime} · ${(p.output.size/1024/1024).toFixed(1)} MB${p.outputStale?' · Có chỉnh sửa chưa xuất lại':''}</p><video class="output-preview" src="${u}" controls playsinline></video><div class="actions"><button class="btn" data-action="close-modal">Đóng</button><button class="btn primary" data-download="${id}">Tải video</button></div>`)}
function downloadBlob(blob,name){const a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000)}
async function downloadVideo(id){const p=state.projects.find(p=>p.id===id),blob=await dbGet('files',p.output.fileId);if(!blob)throw new Error('Không tìm thấy video. Hãy xuất lại.');downloadBlob(blob,p.name.replace(/[^\p{L}\p{N} _-]/gu,'').slice(0,80)+'.'+p.output.ext);toast('Đã bắt đầu tải video.')}
async function backup(){toast('Đang tạo bản sao lưu…');const ids=new Set();for(const p of state.projects){p.scenes.forEach(s=>ids.add(s.fileId));if(p.musicId)ids.add(p.musicId);if(p.voiceId)ids.add(p.voiceId);if(p.output)ids.add(p.output.fileId)}for(const p of state.proProjects||[])for(const a of p.assets||[])ids.add(a.fileId);const files={};for(const id of ids){const blob=await dbGet('files',id);if(!blob)continue;files[id]=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(blob)})}downloadBlob(new Blob([JSON.stringify({format:'remix-studio-backup',version:1,state,files})],{type:'application/json'}),'remix-studio-backup-'+new Date().toISOString().slice(0,10)+'.json');toast('Đã tạo bản sao lưu gồm cấu hình và tư liệu.')}
function validateBackup(data){
const validId=x=>typeof x==='string'&&/^[a-zA-Z0-9-]{1,80}$/.test(x),date=x=>typeof x==='string'&&Number.isFinite(Date.parse(x));
const st=data.state;
for(const p of st.projects){if(!validId(p.id)||typeof p.name!=='string'||!date(p.created)||!date(p.updated)||!/^#[a-fA-F0-9]{6}$/.test(p.color)||!Number.isFinite(p.fontSize)||p.fontSize<20||p.fontSize>70||!['cover','contain'].includes(p.fit)||!Number.isFinite(p.musicVolume)||!Number.isFinite(p.voiceVolume))throw new Error('Cấu hình dự án không hợp lệ.');
for(const s of p.scenes)if(!validId(s.id)||!validId(s.fileId)||typeof s.name!=='string'||typeof s.text!=='string'||!Number.isFinite(s.start)||s.start<0)throw new Error('Tư liệu không hợp lệ.');
for(const id of [p.musicId,p.voiceId])if(id&&!validId(id))throw new Error('Âm thanh không hợp lệ.');
if(p.output&&(!validId(p.output.fileId)||!['mp4','webm'].includes(p.output.ext)||typeof p.output.mime!=='string'||!/^video\/[a-zA-Z0-9;=., _-]+$/.test(p.output.mime)||!Number.isFinite(p.output.size)))throw new Error('Video xuất không hợp lệ.');}
for(const c of st.channels)if(!validId(c.id)||typeof c.name!=='string'||typeof c.username!=='string')throw new Error('Kênh không hợp lệ.');
for(const s of st.schedules)if(!validId(s.id)||!validId(s.projectId)||(s.channelId&&!validId(s.channelId))||!date(s.at)||typeof s.caption!=='string')throw new Error('Kế hoạch không hợp lệ.');
for(const l of st.logs)if(!validId(l.id)||!date(l.at)||typeof l.message!=='string'||!['info','error'].includes(l.type))throw new Error('Nhật ký không hợp lệ.');
}
async function restore(file){if(!file)return;if(file.size>400*1024*1024)throw new Error('Bản sao lưu quá lớn (tối đa 400 MB).');const data=JSON.parse(await file.text());if(data.format!=='remix-studio-backup'||data.version!==1||!Array.isArray(data.state?.projects)||!data.files)throw new Error('Tệp không phải bản sao lưu Remix Studio hợp lệ.');for(const key of ['channels','schedules','logs'])if(!Array.isArray(data.state[key]))throw new Error('Thiếu cấu trúc dữ liệu: '+key);if(!data.state.settings||typeof data.state.settings.name!=='string')throw new Error('Thiếu cài đặt.');for(const p of data.state.projects){if(typeof p.id!=='string'||!Array.isArray(p.scenes)||!['9:16','16:9','1:1'].includes(p.ratio))throw new Error('Dự án không hợp lệ.');for(const s of p.scenes)if(!['image','video'].includes(s.type)||!Number.isFinite(s.duration)||s.duration<=0)throw new Error('Phân cảnh không hợp lệ.')}validateBackup(data);modal(`<h2>Khôi phục bản sao lưu?</h2><p>${data.state.projects.length} dự án sẽ thay thế danh sách hiện tại. Hãy sao lưu dữ liệu hiện tại trước khi tiếp tục.</p><div class="actions"><button class="btn" data-action="close-modal">Hủy</button><button class="btn primary" id="confirm-restore">Khôi phục</button></div>`);$('#confirm-restore').onclick=async()=>{try{for(const [id,url]of Object.entries(data.files)){if(!/^[a-zA-Z0-9-]{1,80}$/.test(id)||typeof url!=='string'||!/^data:(image\/|video\/|audio\/)/.test(url))throw new Error('Tư liệu sao lưu không hợp lệ.');const blob=await(await fetch(url)).blob();await dbPut('files',id,blob)}state=data.state;current=null;for(const u of urls.values())URL.revokeObjectURL(u);urls.clear();log('Khôi phục toàn bộ dự án từ bản sao lưu.');await save();closeModal();await go('home');toast('Đã khôi phục.')}catch(e){report(e)}}}
function report(error){console.error(error);toast(error?.message||'Có lỗi xảy ra. Vui lòng thử lại.');if(state){log(error?.message||'Lỗi không xác định','error');save().catch(()=>{})}}
async function renderVideo(){const p=getProject();if(!p||!p.scenes.length){toast('Thêm ít nhất một ảnh hoặc video trước khi xuất.');return}if(duration(p)>300){toast('Bản trình duyệt hỗ trợ tối đa 5 phút mỗi video.');return}if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream){toast('Thiết bị chưa hỗ trợ xuất. Hãy dùng Chrome/Edge trên máy tính hoặc bộ xuất FFmpeg.');return}stopPreview();rendering=true;cancelRender=false;$('#busy').hidden=false;$('#render-progress').value=0;$('#render-percent').textContent='0%';$('#busy-title').textContent='Đang chuẩn bị tư liệu…';let ctx,rec,stream,raf,media=[],extras=[],sources=[],dest,finished=false;const canvas=document.createElement('canvas');const [w,h]=dimensions(p);canvas.width=w;canvas.height=h;canvas.style.cssText='display:block;max-height:180px;max-width:100%;margin:16px auto;border-radius:6px';$('#busy>div').insertBefore(canvas,$('#render-progress'));try{ctx=new (window.AudioContext||window.webkitAudioContext)();await ctx.resume();dest=ctx.createMediaStreamDestination();const silence=ctx.createOscillator(),silentGain=ctx.createGain();silentGain.gain.value=0;silence.connect(silentGain).connect(dest);silence.start();for(const s of p.scenes){if(cancelRender)throw new Error('Đã hủy xuất video.');media.push(await mediaFor(s))}function route(el,volume){const source=ctx.createMediaElementSource(el),gain=ctx.createGain();gain.gain.value=volume;source.connect(gain).connect(dest);sources.push({source,gain});return gain}const gains=media.map(m=>m instanceof HTMLVideoElement?route(m,p.originalAudio?1:0):null);for(const [id,volume,loop] of [[p.musicId,p.musicVolume,true],[p.voiceId,p.voiceVolume,false]]){if(!id)continue;const el=new Audio();el.preload='auto';el.loop=loop;const pending=loaded(el,'loadeddata');el.src=await fileUrl(id);await pending;route(el,volume);extras.push(el)}paint(canvas,media[0],p.scenes[0],p);stream=canvas.captureStream(30);for(const t of dest.stream.getAudioTracks())stream.addTrack(t);const mime=['video/webm;codecs=vp8,opus','video/webm;codecs=vp9,opus','video/webm','video/mp4'].find(m=>MediaRecorder.isTypeSupported(m));if(!mime)throw new Error('Trình duyệt không có bộ mã hóa video phù hợp.');const chunks=[];rec=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:4500000,audioBitsPerSecond:128000});const recording=new Promise((resolve,reject)=>{rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};rec.onerror=e=>reject(e.error||new Error('Không ghi được video.'));rec.onstop=()=>resolve(new Blob(chunks,{type:rec.mimeType||mime}))});rec.start(1000);for(const el of extras)await el.play();let elapsed=0;for(let i=0;i<media.length;i++){if(cancelRender)break;const m=media[i],s=p.scenes[i];$('#busy-title').textContent=`Đang dựng phân cảnh ${i+1}/${media.length}`;if(m instanceof HTMLVideoElement)await m.play();const t=performance.now();await new Promise(resolve=>{function frame(){const sec=(performance.now()-t)/1000;paint(canvas,m,s,p);stream.getVideoTracks()[0]?.requestFrame?.();const n=Math.min(100,(elapsed+Math.min(sec,s.duration))/duration(p)*100);$('#render-progress').value=n;$('#render-percent').textContent=Math.round(n)+'%';if(cancelRender||sec>=s.duration){resolve();return}raf=requestAnimationFrame(frame)}frame()});if(m instanceof HTMLVideoElement)m.pause();elapsed+=s.duration}rec.stop();const blob=await recording;if(cancelRender)throw new Error('Đã hủy xuất video.');if(blob.size<500)throw new Error('Tệp xuất rỗng. Hãy thử lại trên Chrome/Edge.');const id=uid(),oldOutput=p.output?.fileId;await dbPut('files',id,blob);p.output={fileId:id,size:blob.size,mime:blob.type,ext:blob.type.includes('mp4')?'mp4':'webm',at:new Date().toISOString()};p.outputStale=false;p.demo=false;p.updated=new Date().toISOString();log(`Xuất thành công “${p.name}” · ${p.output.ext.toUpperCase()} · ${time(duration(p))}.`);await save();if(oldOutput){await dbDel('files',oldOutput);if(urls.has(oldOutput)){URL.revokeObjectURL(urls.get(oldOutput));urls.delete(oldOutput)}}finished=true;toast('Video đã được dựng và lưu.');await watch(p.id)}catch(e){if(rec&&rec.state!=='inactive')rec.stop();report(e)}finally{cancelAnimationFrame(raf);for(const el of [...media,...extras])if(el instanceof HTMLMediaElement){el.pause();el.removeAttribute('src');el.load()}for(const {source,gain}of sources){source.disconnect();gain.disconnect()}stream?.getTracks().forEach(t=>t.stop());await ctx?.close().catch(()=>{});canvas.remove();rendering=false;$('#busy').hidden=true;if(finished)nav()}}
const actions={new:newDialog,guide,'close-modal':closeModal,'all-projects':()=>{location.hash='library'},upload:()=>$('#media-input')?.click(),script:scriptDialog,render:renderVideo,preview:playPreview,channel:()=>channelDialog(),schedule:()=>scheduleDialog(),music:()=>audioPicker('music'),voice:()=>audioPicker('voice'),backup,restore:()=>$('#restore-input').click(),'save-settings':async()=>{const name=$('#workspace-name').value.trim();if(!name){toast('Nhập tên không gian.');return}state.settings.name=name;await save();nav();toast('Đã lưu cài đặt.')},persist:async()=>{const ok=await navigator.storage?.persist?.();toast(ok?'Đã bật lưu bền vững cho trình duyệt này.':'Trình duyệt chưa cấp lưu bền vững. Hãy sao lưu thường xuyên.')},'export-logs':()=>downloadBlob(new Blob(['\uFEFFThời gian,Loại,Nội dung\n'+state.logs.map(l=>[fmtDate(l.at),l.type,l.message].map(s=>'"'+String(s).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\n')],{type:'text/csv;charset=utf-8'}),'remix-studio-log.csv')};
function audioPicker(kind){const input=$('#audio-input');input.value='';input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(!f.type.startsWith('audio/'))throw new Error('Chọn tệp âm thanh hợp lệ.');if(f.size>100*1024*1024)throw new Error('Tệp âm thanh tối đa 100 MB.');const p=getProject(),id=uid();await dbPut('files',id,f);p[kind+'Id']=id;p[kind+'Name']=f.name;await updateProject();await editor();toast('Đã thêm âm thanh.')}catch(e){report(e)}};input.click()}
document.addEventListener('click',async e=>{try{const b=e.target.closest('[data-action],[data-open],[data-scene],[data-move],[data-delete-scene],[data-filter],[data-project-menu],[data-watch],[data-download],[data-duplicate],[data-delete-project],[data-channel-edit],[data-channel-delete],[data-schedule-edit],[data-schedule-delete],[data-schedule-done],[data-remove-audio]');if(!b)return;const d=b.dataset;if(d.action){e.preventDefault();await actions[d.action]?.()}else if(d.open){closeModal();current=d.open;selected=0;location.hash='remix';await go('remix')}else if(d.move){e.stopPropagation();const [i,step]=d.move.split(',').map(Number),p=getProject(),next=i+step;if(next>=0&&next<p.scenes.length){[p.scenes[i],p.scenes[next]]=[p.scenes[next],p.scenes[i]];selected=next;await updateProject();await editor()}}else if(d.deleteScene!==undefined){getProject().scenes.splice(Number(d.deleteScene),1);await updateProject();await editor()}else if(d.scene!==undefined){stopPreview();selected=Number(d.scene);await editor()}else if(d.filter){window.libraryFilter=d.filter;await library()}else if(d.projectMenu)projectMenu(d.projectMenu);else if(d.watch)await watch(d.watch);else if(d.download)await downloadVideo(d.download);else if(d.duplicate){const old=state.projects.find(p=>p.id===d.duplicate),p=structuredClone(old);p.id=uid();p.name+=' (bản sao)';p.created=p.updated=new Date().toISOString();p.output=null;p.demo=false;state.projects.unshift(p);log(`Nhân bản “${old.name}”.`);await save();closeModal();await go(page);toast('Đã nhân bản dự án.')}else if(d.deleteProject){const p=state.projects.find(p=>p.id===d.deleteProject);modal(`<h2>Xóa dự án?</h2><p>“${esc(p.name)}” và các kế hoạch liên quan sẽ bị xóa. Bạn có thể tải bản sao lưu trước khi thực hiện.</p><div class="actions"><button class="btn" data-action="close-modal">Giữ lại</button><button class="btn danger" id="confirm-delete">Xóa dự án</button></div>`);$('#confirm-delete').onclick=async()=>{state.projects=state.projects.filter(x=>x.id!==p.id);state.schedules=state.schedules.filter(s=>s.projectId!==p.id);if(current===p.id)current=null;log(`Xóa dự án “${p.name}”.`);await save();await collectFiles();closeModal();await go(page);toast('Đã xóa dự án.')}}else if(d.channelEdit)channelDialog(d.channelEdit);else if(d.channelDelete){const ch=state.channels.find(c=>c.id===d.channelDelete);modal(`<h2>Gỡ thông tin kênh?</h2><p>@${esc(ch.username)} sẽ được gỡ khỏi danh sách. Những kế hoạch liên quan sẽ không còn chọn kênh.</p><div class="actions"><button class="btn" data-action="close-modal">Giữ lại</button><button class="btn danger" id="confirm-channel-delete">Gỡ kênh</button></div>`);$('#confirm-channel-delete').onclick=async()=>{state.channels=state.channels.filter(c=>c.id!==ch.id);state.schedules.forEach(s=>{if(s.channelId===ch.id)s.channelId=''});log(`Gỡ thông tin kênh @${ch.username}.`);await save();closeModal();await go('channels')}}else if(d.scheduleEdit)scheduleDialog(d.scheduleEdit);else if(d.scheduleDelete){state.schedules=state.schedules.filter(s=>s.id!==d.scheduleDelete);log('Xóa một kế hoạch đăng.');await save();calendar()}else if(d.scheduleDone){const s=state.schedules.find(s=>s.id===d.scheduleDone);s.done=!s.done;log(s.done?'Người dùng đánh dấu đã đăng thủ công.':'Người dùng hoàn tác trạng thái đã đăng.');await save();calendar()}else if(d.removeAudio){const p=getProject();p[d.removeAudio+'Id']=null;p[d.removeAudio+'Name']='';await updateProject();await editor()}}catch(error){report(error)}});
async function collectFiles(){const used=new Set();for(const p of state.projects){p.scenes.forEach(s=>used.add(s.fileId));[p.musicId,p.voiceId,p.output?.fileId].filter(Boolean).forEach(id=>used.add(id))}for(const p of state.proProjects||[])for(const a of p.assets||[])used.add(a.fileId);const keys=await new Promise((resolve,reject)=>{const r=db.transaction('files').objectStore('files').getAllKeys();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});for(const id of keys)if(!used.has(id)){await dbDel('files',id);if(urls.has(id)){URL.revokeObjectURL(urls.get(id));urls.delete(id)}}}
$('#help').onclick=guide;$('#footer-help').onclick=guide;$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#cancel-render').onclick=()=>{cancelRender=true;$('#busy-title').textContent='Đang hủy xuất…'};$('#modal').addEventListener('close',()=>{$$('#modal video').forEach(v=>v.pause())});window.addEventListener('hashchange',()=>go(location.hash.slice(1)).catch(report));window.addEventListener('beforeunload',e=>{if(rendering){e.preventDefault();e.returnValue='Video đang được dựng.'}});
(async()=>{try{await dbReady;state=await dbGet('state','workspace');if(!state)await seed();await go(location.hash.slice(1)||'home')}catch(error){$('#main').innerHTML='<div class="panel"><h1>Không thể mở dữ liệu trên thiết bị</h1><p>Trình duyệt cần cho phép IndexedDB. Hãy thử Chrome/Edge ở chế độ thông thường.</p></div>';console.error(error)}})();
